<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { api,products } from '../api'
import { useAuthStore } from '../stores/auth'
import type { Page,Product,Batch } from '../types'
const auth=useAuthStore(),manager=computed(()=>auth.user?.role!=='CLERK'),operator=computed(()=>auth.user?.role!=='MANAGER')
const rows=ref<Page<any>>(),catalog=ref<Product[]>([]),batches=ref<Batch[]>([]),index=ref(0),open=ref(false),loading=ref(false),saving=ref(false)
const form=reactive({kind:'COUNT',productId:undefined as number|undefined,batchId:undefined as number|undefined,quantity:0,reason:''})
async function load(){loading.value=true;try{rows.value=(await api.get('/stock-reviews',{params:{page:index.value,size:20}})).data}catch{ElMessage.error('Could not load stock reviews')}finally{loading.value=false}}
onMounted(async()=>{await load();catalog.value=(await products({size:100})).items});watch(index,load)
watch(()=>form.productId,async id=>{form.batchId=undefined;if(id)batches.value=(await api.get('/batches',{params:{productId:id,size:100}})).data.items})
async function submit(){if(!form.productId||!form.reason.trim())return ElMessage.warning('Select a product and provide a reason');saving.value=true;try{await api.post('/stock-reviews',{...form,batchId:form.kind==='DISPOSAL'?form.batchId:null});open.value=false;await load();ElMessage.success('Submitted for approval')}catch(e:any){ElMessage.error(e.response?.data?.message||'Could not submit review')}finally{saving.value=false}}
async function act(row:any,action:string){try{const {value}=await ElMessageBox.prompt('Review note',action,{inputValidator:v=>!!v?.trim()||'Note is required'});saving.value=true;await api.post(`/stock-reviews/${row.id}/actions`,{action,note:value});await load();ElMessage.success('Review completed')}catch(e:any){if(e.response)ElMessage.error(e.response.data?.message||'Could not review request')}finally{saving.value=false}}
</script>
<template><section class="view table-view" v-loading="loading"><div class="page-heading"><h1>Stock reviews</h1><el-button v-if="operator" type="primary" @click="Object.assign(form,{kind:'COUNT',productId:undefined,batchId:undefined,quantity:0,reason:''});open=true">New request</el-button></div><div class="surface-card table-surface"><el-table :data="rows?.items||[]" stripe><el-table-column prop="id" label="REQUEST" width="100"/><el-table-column prop="kind" label="TYPE" width="140"/><el-table-column prop="productName" label="PRODUCT" min-width="190"/><el-table-column prop="batchNumber" label="BATCH" min-width="150"/><el-table-column prop="quantity" label="QUANTITY" width="100"/><el-table-column prop="snapshotQuantity" label="SNAPSHOT" width="110"/><el-table-column prop="state" label="STATUS" width="130"/><el-table-column prop="reason" label="REASON" min-width="180"/><el-table-column prop="reviewNote" label="REVIEW NOTE" min-width="180"/><el-table-column prop="createdBy" label="REQUESTED BY" min-width="140"/><el-table-column prop="reviewedBy" label="REVIEWED BY" min-width="140"/><el-table-column v-if="manager" width="200"><template #default="{row}"><template v-if="row.state==='SUBMITTED'"><el-button :disabled="saving" @click="act(row,'APPROVE')">Approve</el-button><el-button :disabled="saving" @click="act(row,'REJECT')">Reject</el-button></template></template></el-table-column></el-table><div class="table-pagination"><span>{{ rows?.totalElements||0 }} requests</span><el-pagination :current-page="index+1" @current-change="index=$event-1" :total="rows?.totalElements||0" :page-size="20" layout="prev, pager, next"/></div></div><el-dialog v-model="open" title="Stock review request" width="560px"><el-form label-position="top"><el-form-item label="Request type"><el-select v-model="form.kind"><el-option label="Physical stock count" value="COUNT"/><el-option label="Batch disposal" value="DISPOSAL"/><el-option label="Stock adjustment" value="ADJUSTMENT"/></el-select></el-form-item><el-form-item label="Product"><el-select v-model="form.productId" filterable><el-option v-for="p in catalog" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item v-if="form.kind==='DISPOSAL'" label="Batch"><el-select v-model="form.batchId"><el-option v-for="b in batches.filter(b=>b.quantity>0)" :key="b.id" :label="`${b.batchNumber} · ${b.quantity} · ${b.status}`" :value="b.id"/></el-select></el-form-item><el-form-item :label="form.kind==='COUNT'?'Counted physical quantity':form.kind==='ADJUSTMENT'?'Quantity change (+ or −)':'Disposal quantity'"><el-input-number v-model="form.quantity" :min="form.kind==='ADJUSTMENT'?-1000000000:form.kind==='COUNT'?0:1" :max="1000000000" :precision="0"/></el-form-item><el-form-item label="Reason and evidence notes"><el-input v-model="form.reason" type="textarea" maxlength="300" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="open=false">Cancel</el-button><el-button type="primary" :loading="saving" @click="submit">Submit request</el-button></template></el-dialog></section></template>
